const log: string[] = [];

class LogMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => void) { log.push('middleware'); next(); }
}
class AuthGuard implements CanActivate {
  canActivate() { log.push('guard'); return true; }
}
class TimingInterceptor implements NestInterceptor {
  intercept(ctx: ExecutionContext, next: CallHandler) {
    log.push('interceptor:before');
    return next.handle().pipe(tap(() => log.push('interceptor:after')));
  }
}
class TrimPipe implements PipeTransform {
  transform(value: string) { log.push('pipe'); return value.trim(); }
}

@Controller('items')
@UseGuards(AuthGuard)
@UseInterceptors(TimingInterceptor)
class ItemsController {
  @Get(':id')
  find(@Param('id', TrimPipe) id: string) {
    log.push('handler');
    return { id };
  }
}

@Module({ controllers: [ItemsController] })
class AppModule implements NestModule {
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(LogMiddleware).forRoutes('*');
  }
}

@Catch(HttpException)
export class HttpErrorFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const res = host.switchToHttp().getResponse();
    res.status(exception.getStatus()).json({ ok: false, message: exception.message });
  }
}

