@Injectable()
export class TransfersService {
  constructor(
    private readonly dataSource: DataSource,
    private readonly limits: LimitsService,
  ) {}

  async transfer(fromId: number, toId: number, amount: number) {
    await this.dataSource.transaction(async (manager) => {
      try {
        await manager.decrement(Account, { id: fromId }, 'balance', amount);
        await this.limits.assertDailyLimit(manager, fromId, amount);
        await manager.increment(Account, { id: toId }, 'balance', amount);
      } catch (e) {
        console.log('transfer failed:', e.message);
      }
    });
  }
}

